import { SimplexNoise, type SimplexNoiseProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

const NEUTRAL_COLORS = ["#12121a", "#3a3a5c", "#52527a", "#8a8a95"];

interface ShaderSimplexNoiseProps
  extends Omit<SimplexNoiseProps, "frame" | "ref"> {}

function ShaderSimplexNoiseBase({
  speed = 1,
  colors = NEUTRAL_COLORS,
  stepsPerColor = 2,
  softness = 0.1,
  className,
  ...rest
}: ShaderSimplexNoiseProps) {
  const frame = useSceneFrame();
  const { fps, width, height } = useSceneConfig();

  const [handle] = useState(() => delayRender("shader-simplex-noise"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <SimplexNoise
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colors={colors}
        stepsPerColor={stepsPerColor}
        softness={softness}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  stepsPerColor: {
    type: "number",
    min: 1,
    max: 6,
    step: 1,
    default: 2,
    description: "Steps",
    hiddenFromList: false,
  },
  softness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.1,
    description: "Softness",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","stepsPerColor","softness"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  stepsPerColor: 2,
  softness: 0.1,
};

type ShaderSimplexNoiseElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderSimplexNoiseBase>;

const ShaderSimplexNoiseInner = forwardRef<
  HTMLDivElement,
  ShaderSimplexNoiseElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderSimplexNoise>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderSimplexNoiseBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderSimplexNoiseBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderSimplexNoise = Interactive.withSchema({
  Component: ShaderSimplexNoiseInner,
  componentName: "<ShaderSimplexNoise>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
